// DomyÅ›lna liczba wierszy rÃ³wna liczbie kolumn
$grid-rows: $grid-columns !default;

// DefiniujÄ™ mapÄ™ z breakpointami (od najwiÄ™kszego do najmniejszego)
// Ta kolejnoÅ›Ä‡ jest kluczowa dla prawidÅ‚owego nadpisywania styli w media queries
$breakpoints: (
  "xl": $breakpoint-xl,
  "lg": $breakpoint-lg,
  "md": $breakpoint-md,
  "sm": $breakpoint-sm,
  "xs": $breakpoint-xs,
  "xxs": $breakpoint-xxs
);

// Mixin do ustawiania grid-column
@mixin grid-column-pos($start, $end) {
  grid-column: #{$start}/#{$end};
}

// Mixin do ustawiania grid-row
@mixin grid-row-pos($start, $end) {
  grid-row: #{$start}/#{$end};
}

// Generowanie klas utility dla kolumn
// Najpierw generujemy podstawowe klasy bez media queries
@for $i from 1 through ($grid-columns + 2) {
  @for $j from ($i + 1) through ($grid-columns + 3) {
    .gc-#{$i}\/#{$j} {
      @include grid-column-pos($i, $j);
    }
  }
}

// Potem generujemy media queries osobno, wyraÅºnie oddzielone dla kaÅ¼dego breakpointu
// DziÄ™ki temu wszystkie media queries dla danego breakpointu bÄ™dÄ… zgrupowane razem
// Zaczynamy od najwiÄ™kszego breakpointu (xl) i idziemy do najmniejszego (xxs)
// KolejnoÅ›Ä‡ ma znaczenie! Najmniejsze breakpointy bÄ™dÄ… na koÅ„cu pliku i nadpiszÄ… wiÄ™ksze
@each $breakpoint-name, $breakpoint-value in $breakpoints {
  @media screen and (max-width: #{$breakpoint-value}) {
    @for $i from 1 through ($grid-columns + 2) {
      @for $j from ($i + 1) through ($grid-columns + 3) {
        .gc-#{$breakpoint-name}-#{$i}\/#{$j} {
          grid-column: #{$i}/#{$j} !important;
        }
      }
    }
  }
}

// Generowanie klas utility dla wierszy
// Najpierw generujemy podstawowe klasy bez media queries
@for $i from 1 through $grid-rows {
  @for $j from ($i + 1) through ($grid-rows + 2) {
    .gr-#{$i}\/#{$j} {
      @include grid-row-pos($i, $j);
    }
  }
}

// Potem generujemy media queries osobno dla kaÅ¼dego breakpointu
// PorzÄ…dek od najwiÄ™kszego do najmniejszego breakpointu
@each $breakpoint-name, $breakpoint-value in $breakpoints {
  @media screen and (max-width: #{$breakpoint-value}) {
    @for $i from 1 through $grid-rows {
      @for $j from ($i + 1) through ($grid-rows + 2) {
        .gr-#{$breakpoint-name}-#{$i}\/#{$j} {
          grid-row: #{$i}/#{$j} !important;
        }
      }
    }
  }
}


